import {advancedDefinition,abilityEvolutionOptions} from './advanced-powers.mjs';
import {coreAbility,powerCatalog,activePowers,powerDescription,ABILITY_LIMIT,MAX_ABILITY_RANK} from './powers.mjs';
import {buildLocked} from './management.mjs';
import {skillIcon} from './skillbook.mjs';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph=id=>id==='ability-absorption'||id==='passive-vitality'?'mend':id.includes('ward')||id.includes('resolve')?'guard':id==='ability-concentration'?'stance':'focus';
export function powersPanel(s){
 const core=coreAbility(s),all=powerCatalog(s),active=activePowers(s),locked=buildLocked(s);
 return `<section class="build-panel powers-panel"><h1 id="scene-title" tabindex="-1">능력</h1><p class="power-intro">상시·조건부 효과 · Lv.7에서 세 진화 중 하나 선택</p>${s.scene==='ability-evolution'?'<button class="primary" data-tab="story">진화 선택으로 돌아가기</button>':''}<p id="build-note" role="status"></p>${core?`<section class="innate-power"><button data-power="core-breath" class="power-inspect"><span class="power-glyph">${skillIcon('focus')}</span><span><small>숨의 길 · 고유 능력</small><strong>${core.name} <b>Lv.${core.level}/${MAX_ABILITY_RANK+1}</b></strong></span></button><p>${esc(core.description)}</p><small>항상 적용 · 활성 칸을 사용하지 않음</small></section>`:'<p class="empty-note">숨의 길을 정하면 고유 능력이 열립니다.</p>'}<div class="section-title"><h2>활성 능력</h2><span>${active.length} / ${ABILITY_LIMIT}</span></div><div class="power-slots">${Array.from({length:ABILITY_LIMIT},(_,i)=>`<span class="${active[i]?'filled':''}">${active[i]?esc(active[i].name.replace(/ \+\d+$/,''))+' Lv.'+active[i].level:'빈 능력 칸'}</span>`).join('')}</div>${locked?`<p class="build-lock">${s.journey?.points?'성장 보상 선택 후':'전투 종료 후'} 활성 구성을 바꿀 수 있습니다.</p>`:''}<div class="power-grid">${all.filter(a=>s.passiveSkills?.includes(a.id)).map(a=>{const owned=s.passiveSkills?.includes(a.id),enabled=active.some(x=>x.id===a.id);return `<article class="power-card ${owned?'owned':'unowned'} ${enabled?'enabled':''}"><button class="power-inspect" data-power="${a.id}" aria-label="${esc(a.name)} 능력 상세"><span class="power-glyph">${skillIcon(glyph(a.id))}</span><span><strong>${esc(a.name.replace(/ \+\d+$/,''))}</strong><small>${owned?'Lv.'+a.level+'/'+(MAX_ABILITY_RANK+1)+(enabled?' · 활성':' · 비활성'):'미획득'}</small></span></button><p>${esc(powerDescription(s,a))}</p>${owned?`<button class="quiet manage-action" data-manage="power" data-id="${a.id}" ${locked?'disabled':''}>${enabled?'비활성화':'활성화'}</button>`:'<small>성장 보상 · 공방에서 획득</small>'}</article>`;}).join('')}</div><details class="power-library"><summary>미획득 능력 사전 · ${all.filter(a=>!s.passiveSkills?.includes(a.id)).length}종</summary><div class="power-grid">${all.filter(a=>!s.passiveSkills?.includes(a.id)).map(a=>`<article class="power-card unowned"><button class="power-inspect" data-power="${a.id}"><strong>${esc(a.name)}</strong></button><p>${esc(powerDescription(s,a))}</p></article>`).join('')}</div></details></section>`;
}
export function powerDialog(s,id){const a=id==='core-breath'?coreAbility(s):powerCatalog(s).find(a=>a.id===id);if(!a)return '';const owned=a.innate||s.passiveSkills?.includes(a.id),enabled=a.innate||s.passiveLoadout?.includes(a.id),description=a.innate?a.description:powerDescription(s,a);return `<section class="power-detail"><p class="eyebrow">${a.innate?'고유 능력':'상시·조건부 능력'}</p><h2>${esc(a.name.replace(/ \+\d+$/,''))}</h2><p>${owned?'Lv.'+a.level+'/'+(MAX_ABILITY_RANK+1):'미획득'} · ${enabled?'적용 중':'미적용'}</p><p>${esc(description)}</p><p class="muted">스킬의 사용 횟수·쿨타임·장착 칸을 소비하지 않습니다. 능력 레벨은 스킬 강화와 따로 저장됩니다.</p>${evolutionPreview(s,a)}${a.rank<MAX_ABILITY_RANK?`<p class="power-next">다음 레벨 · ${esc(a.innate?coreAbility({...s,innateRank:a.rank+1}).description:powerDescription(s,{...a,rank:a.rank+1,description:nextPassiveDescription(a)}))}</p>`:''}</section>`;}
function nextPassiveDescription(a){const bonus=powerCatalog({passiveRanks:{[a.id]:a.rank+1}}).find(x=>x.id===a.id);return bonus.description;}
export function powerBattleSummary(s){const core=coreAbility(s),active=activePowers(s),events=s.battle?.abilityEvents||[];return `<details class="battle-powers"><summary>능력 · ${core?core.name+' Lv.'+core.level:''} · 활성 ${active.length}/${ABILITY_LIMIT}</summary><div>${active.map(a=>`<button class="power-badge" data-power="${a.id}">${esc(a.name.replace(/ \+\d+$/,''))} Lv.${a.level}</button>`).join('')||'<span>활성화한 추가 능력 없음</span>'}<button class="quiet" data-tab="powers">능력 보기</button></div></details>${events.length?`<div class="ability-events" aria-label="자동 발동한 능력">${events.map(e=>`<span>능력 · ${esc(e.name)} · ${esc(e.text)}</span>`).join('')}</div>`:''}`;}

function evolutionPreview(s,a){const row=advancedDefinition(a.id),chosen=s.powerEvolutions?.[a.id];return (row?'<div class="power-levels" aria-label="레벨별 능력 수치">'+row.table.map((v,i)=>'<span class="'+(i===a.rank?'current':'')+'">Lv.'+(i+1)+'<b>'+v+'</b></span>').join('')+'</div>':'')+'<h3>Lv.7 진화 · 하나 선택</h3><div class="evolution-previews">'+abilityEvolutionOptions(a.id).map(e=>'<article class="'+(chosen===e.id?'chosen':'')+'"><strong>'+esc(e.name)+(chosen===e.id?' · 선택됨':'')+'</strong><p>'+esc(e.description)+'</p></article>').join('')+'</div>';}
